/*
** My participation to Genuary 2025
** https://genuary.art/
** Prompt of the day : Vertical or horizontal lines only.
*/

#define sat(a) clamp(a, 0., 1.)
#define rot(a) mat2(cos(a), -sin(a), sin(a), cos(a))

vec2 _min(vec2 a, vec2 b)
{
    if (a.x < b.x)
        return a;
    return b;
}

float _sqr(vec2 uv, vec2 s)
{
    vec2 l = abs(uv)-s;
    return max(l.x, l.y);
}

float _cube(vec3 p, vec3 s)
{
    vec3 l = abs(p)-s;
    return max(l.x, max(l.y, l.z));
}

float _cucube(vec3 p, vec3 s, vec3 th)
{
    float c = _cube(p, s);

    c = max(c, -_sqr(p.xy, s.xy-th.xy));
    c = max(c, -_sqr(p.yz, s.yz-th.yz));
    c = max(c, -_sqr(p.xz, s.xy-th.xz));
    return c;
}

vec2 map(vec3 p)
{
    vec2 acc = vec2(1000.,-1.);
    vec2 vxz = vec2(.03);
    p.xz = floor(p.xz/vxz)*vxz;
    vec3 pc = p;
    pc.xy *= rot(iTime*.1);
    pc.yz *= rot(iTime*.25);
    float outcube = _cube(pc, vec3(1.-.01));
    float cube = _cucube(pc, vec3(1.), vec3(.01));
    acc = _min(acc, vec2(cube, 1.));

    float blob = texture(iChannel0, p*.1+iTime*.01).x-.3
    +texture(iChannel0, -p*.1-vec3(1.,-1.,.3)*iTime*.01).x-.5;
    blob = max(blob, outcube);
    acc = _min(acc, vec2(blob, 2.));
    return acc;
}

vec3 getNorm(vec3 p)
{
    vec2 e = vec2(0.01,0.);
    float d = map(p+e.xxx).x;
    return normalize(vec3(d)-vec3(
        map(p-e.xyy).x,
        map(p-e.yxy).x,
        map(p-e.yyx).x));
}

vec3 rdr(vec2 uv)
{
    vec3 col = vec3(.2,.1,.3)*(1.-sat(length(uv)*1.5));

    vec3 ro = vec3(0.,0.,-5.);
    vec3 rd = normalize(vec3(uv, 1.));
    vec3 p = ro;
    for (int i = 0; i < 256; ++i)
    {
        vec2 res = map(p);
        if (distance(p, ro) > 510.)
            break;
        if (res.x < 0.01)
        {
            col = vec3(1.);
            vec3 n = getNorm(p);
            if (res.y == 2.) {
                col = (n*.5+.5).zxy;
                col.xy *= rot(4.28);
                col.yz *= rot(37.04);
            }
            break;
        }
        p+= rd * res.x*.1;
    }
    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.xx;

    vec3 col = rdr(uv*1.5);

    fragColor = vec4(col,1.0);
}
